import random
import threading
import time
from enum import Enum
from typing import Dict, List, Optional, Tuple, Set
from dataclasses import dataclass, field
from collections import defaultdict

# =====================
# Core Data Structures
# =====================

class Ability(Enum):
    STRENGTH = "strength"
    AGILITY = "agility"
    INTELLIGENCE = "intelligence"
    STEALTH = "stealth"

class EnvironmentType(Enum):
    FOREST = "forest"
    CAVE = "cave"
    RUINS = "ruins"

class GameState(Enum):
    LOBBY = "lobby"
    PLAYING = "playing"
    FINISHED = "finished"

@dataclass
class Player:
    id: int
    name: str
    ability: Ability
    team_id: int
    position: Tuple[int, int] = (0, 0)
    treasures_collected: int = 0
    alive: bool = True

    def __hash__(self):
        return hash(self.id)

@dataclass
class Puzzle:
    required_abilities: Set[Ability]
    description: str
    reward: int = 1
    solved: bool = False

    def can_solve(self, team_abilities: Set[Ability]) -> bool:
        return self.required_abilities.issubset(team_abilities)

@dataclass
class Room:
    name: str
    environment: EnvironmentType
    puzzles: List[Puzzle] = field(default_factory=list)
    treasures: int = 0
    connections: Dict[str, 'Room'] = field(default_factory=dict)  # direction -> Room
    locked: bool = False
    lock_requirement: Optional[Ability] = None

    def __post_init__(self):
        if self.connections is None:
            self.connections = {}

@dataclass
class Team:
    id: int
    name: str
    players: List[Player] = field(default_factory=list)
    current_room: Optional[Room] = None
    treasures_collected: int = 0
    start_time: Optional[float] = None
    end_time: Optional[float] = None

    def get_abilities(self) -> Set[Ability]:
        return {p.ability for p in self.players if p.alive}

    def get_position(self) -> Tuple[int, int]:
        if self.current_room:
            return self.current_room.name
        return (0, 0)

# =====================
# Game Engine
