import random
import threading
import time
from collections import defaultdict
from dataclasses import dataclass, field
from enum import Enum
from typing import Dict, List, Optional, Tuple, Set


class Ability(Enum):
    STRENGTH = "strength"
    AGILITY = "agility"
    INTELLIGENCE = "intelligence"
    STEALTH = "stealth"


class EnvironmentType(Enum):
    FOREST = "forest"
    CAVE = "cave"
    RUINS = "ruins"


@dataclass
class Player:
    id: int
    name: str
    ability: Ability
    team: str
    position: Tuple[int, int] = (0, 0)
    treasures: int = 0
    alive: bool = True
    active_puzzle: Optional[str] = None

    def move(self, dx: int, dy: int) -> bool:
        if not self.alive:
            return False
        self.position = (self.position[0] + dx, self.position[1] + dy)
        return True

    def use_ability(self, puzzle_type: str) -> bool:
        """Check if player's ability is suitable for the puzzle type."""
        mapping = {
            "heavy": Ability.STRENGTH,
            "tight": Ability.AGILITY,
            "logic": Ability.INTELLIGENCE,
            "trap": Ability.STEALTH,
        }
        return self.ability == mapping.get(puzzle_type)


@dataclass
class Puzzle:
    id: str
    type: str  # 'heavy', 'tight', 'logic', 'trap'
    required_solvers: int = 1
    solved: bool = False
    location: Tuple[int, int] = (0, 0)
    reward: int = 1


@dataclass
class Treasure:
    id: str
    location: Tuple[int, int]
    value: int = 1
    collected: bool = False


@dataclass
class Environment:
    name: str
    type: EnvironmentType
    size: Tuple[int, int]  # (width, height)
    puzzles: List[Puzzle] = field(default_factory=list)
    treasures: List[Treasure] = field(default_factory=list)
    hazards: Set[Tuple[int, int]] = field(default_factory=set)

    def is_valid_position(self, pos: Tuple[int, int]) -> bool:
        x, y = pos
        w, h = self.size
        return 0 <= x < w and 0 <= y < h and pos not in self.hazards


class GameEngine:
    def __init__(self, max_teams: int = 4, max_players_per_team: int = 4):
        self.teams: Dict[str, List[Player]] = defaultdict(list)
        self.environments: List[Environment] = []
        self.current_env_index: int = 0
        self.final_chamber_reached: Set[str] = set()
        self.game_over: bool = False
        self.start_time: Optional[float] = None
        self.lock = threading.Lock()
        self.max_teams = max_teams
        self.max_players_per_team = max_players_per_team

    def add_team(self, team_name: str, players: List[Player]) -> bool:
        if len(self.teams) >= self.max_teams:
            return False
        if len(players) > self.max_players_per_team:
            return False
        if any(p.team != team_name for p in players):
            return False
        self.teams[team_name] = players
        return True

    def add_environment(self, env: Environment):
        self.environments.append(env)

    def start_game(self):
        if not self.teams or not self.environments:
            raise ValueError("Game must have at least one team and one environment.")
        self.start_time = time.time()

    def get_current_environment(self) -> Environment:
        return self.environments[self.current_env_index]

    def move_player(self, player_id: int, dx: int, dy: int) -> Dict:
        with self.lock:
            player = self._find_player_by_id(player_id)
            if not player or not player.alive:
                return {"success": False, "error": "Player not found or dead"}

            current_env = self.get_current_environment()
            new_pos = (player.position[0] + dx, player.position[1] + dy)

            if not current_env.is_valid_position(new_pos):
                return {"success": False, "error": "Invalid move"}

            player.move(dx, dy)

            # Check for treasure
            for treasure in current_env.treasures:
                if not treasure.collected and treasure.location == player.position:
                    treasure.collected = True
                    player.treasures += treasure.value

            # Check for puzzle
            for puzzle in current_env.puzzles:
                if not puzzle.solved and puzzle.location == player.position:
                    return self.attempt_solve_puzzle(player, puzzle)

            return {
                "success": True,
                "position": player.position,
                "treasures_collected": player.treasures,
            }

    def attempt_solve_puzzle(self, player: Player, puzzle: Puzzle) -> Dict:
        # Check if puzzle is already being solved by another player
        if puzzle.active_solvers:
            return {"success": False, "error": "Puzzle already being solved"}

        # Record solver
        puzzle.active_solvers.add(player.id)

        # Simulate solving (in real game, would wait for all required solvers)
        time.sleep(0.1)  # Simulate solving time

        # Check if player's ability matches puzzle type
        if player.use_ability(puzzle.type):
            puzzle.solved = True
            puzzle.active_solvers.clear()
            return {
                "success": True,
                "puzzle_id": puzzle.id,
                "reward": puzzle.reward,
                "message": "Puzzle solved!"
            }
        else:
            puzzle.active_solvers.discard(player.id)
            return {
                "success": False,
                "puzzle_id": puzzle.id,
                "error": "Your ability does not match puzzle type. Required: " + puzzle.type
            }

    def _find_player_by_id(self, player_id: int) -> Optional[Player]:
        for team_players in self.teams.values():
            for player in team_players:
                if player.id == player_id:
                    return player
        return None

    def check_final_chamber(self, player: Player) -> Dict:
        current_env = self.get_current_environment()
        if current_env.type == EnvironmentType.RUINS and player.position == (current_env.size[0] - 1, current_env.size[1] - 1):
            with self.lock:
                if player.team not in self.final_chamber_reached:
                    self.final_chamber_reached.add(player.team)
                    if len(self.final_chamber_reached) == 1:
                        self.end_game()
            return {"success": True, "message": f"Team {player.team} reached the final chamber!"}
        return {"success": False}

    def end_game(self):
        with self.lock:
            if self.game_over:
                return
            self.game_over = True
            elapsed_time = time.time() - self.start_time

            # Calculate scores
            scores = {}
            for team_name, players in self.teams.items():
                total_treasures = sum(p.treasures for p in players)
                # Bonus for time: faster teams get bonus points
                time_bonus = max(0, int(100 - elapsed_time))
                scores[team_name] = total_treasures * 10 + time_bonus

            self.final_scores = scores
            self.elapsed_time = elapsed_time

    def get_game_state(self) -> Dict:
        with self.lock:
            current_env = self.get_current_environment()
            return {
                "current_environment": current_env.name,
                "teams": {
                    team: [
                        {
                            "id": p.id,
                            "name": p.name,
                            "ability": p.ability.value,
                            "position": p.position,
                            "treasures": p.treasures,
                            "alive": p.alive,
                        }
                        for p in players
                    ]
                    for team, players in self.teams.items()
                },
                "puzzles": [
                    {"id": p.id, "type": p.type, "solved": p.solved, "location": p.location}
                    for p in current_env.puzzles
                ],
